      let over = max(peak - params.threshold, 0.0) / max(peak, 1e-4);
      let q = (p - vec2f(0.5)) * vec2f(aspect, 1.0);
      let onAxis = exp(-dot(q, q) / (2.0 * params.axis * params.axis));
      sum = sum + c * over * onAxis;
