@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  var rgb = vec3f(0.0);
  var at = vec2f(0.0);
  var total = 0.0;
  for (var j = 0; j < 26; j = j + 1) {
    for (var i = 0; i < 60; i = i + 1) {
      let c = textureLoad(inputTexture, vec2i(i, j), 0).rgb;
