// T1383b: the camera's right vector with its ROLL — world up turned about the view axis by
// roll degrees (Rodrigues), exactly as camera.ts guardedRolledUp builds the render's view.
fn rolledRight(forward: vec3f, rollDeg: f32) -> vec3f {
  var up = select(vec3f(0.0, 1.0, 0.0), vec3f(0.0, 0.0, 1.0), abs(forward.y) > 0.999);
  let t = radians(rollDeg);
  up = up * cos(t) + cross(forward, up) * sin(t) + forward * dot(forward, up) * (1.0 - cos(t));
  return normalize(cross(forward, up));
}

struct View {
  forward: vec3f,
  right: vec3f,
  up: vec3f,
  tanHalf: f32,
  aspect: f32,
};

fn makeView() -> View {
  var v: View;
  v.forward = normalize(params.aim - params.eye);
  v.right = rolledRight(v.forward, params.roll);
  v.up = cross(v.right, v.forward);
  v.tanHalf = tan(radians(params.fov) * 0.5);
  v.aspect = frameU.resolution.x / max(frameU.resolution.y, 1.0);
  return v;
}

fn rayAt(v: View, uv: vec2f) -> vec3f {
  let ndc = vec2f(uv.x * 2.0 - 1.0, 1.0 - uv.y * 2.0);
  return normalize(v.forward + v.right * ndc.x * v.tanHalf * v.aspect + v.up * ndc.y * v.tanHalf);
}

fn depthTexel(uv: vec2f) -> vec2i {
  let size = vec2f(textureDimensions(inputTexture1));
  return clamp(vec2i(uv * size), vec2i(0), vec2i(size) - vec2i(1));
}

// View-plane distance at uv, or a negative number where there is no surface.
fn viewDepth(uv: vec2f) -> f32 {
  let d = textureLoad(inputTexture1, depthTexel(uv), 0).r;
  return select(d * params.far, -1.0, d >= 0.9999 || d <= 0.0);
}

fn worldAt(v: View, uv: vec2f, z: f32) -> vec3f {
  let ray = rayAt(v, uv);
  return params.eye + ray * (z / max(dot(ray, v.forward), 1e-4));
}

// World point → (uv, view-plane distance); z ≤ 0 means behind the camera.
fn project(v: View, world: vec3f) -> vec3f {
  let rel = world - params.eye;
  let z = dot(rel, v.forward);
  let x = dot(rel, v.right) / (max(z, 1e-4) * v.tanHalf * v.aspect);
  let y = dot(rel, v.up) / (max(z, 1e-4) * v.tanHalf);
  return vec3f(x * 0.5 + 0.5, 0.5 - y * 0.5, z);
}

fn ignHash(pixel: vec2f) -> f32 {
  return fract(52.9829189 * fract(dot(pixel, vec2f(0.06711056, 0.00583715))));
}

const LIGHTS: u32 = 2u;
const L_POS = array<vec3f, 2>(
  vec3f(0.70081, 0.93676, -0.26165),
  vec3f(-0.70080, 0.93676, -0.26162));
const L_DIR = array<vec3f, 2>(
  vec3f(0.00000, -0.05989, 0.99820),
  vec3f(0.00000, -0.05989, 0.99820));
const L_COLOR = array<vec3f, 2>(
  vec3f(2.41800, 2.49600, 2.60000),
  vec3f(2.41800, 2.49600, 2.60000));
const L_SHAPE = array<vec4f, 2>(
  vec4f(0.88701, 0.97677, 0.0, 0.0),
  vec4f(0.88701, 0.97677, 0.0, 0.0));
const STEPS: u32 = 72u;

fn hg(cosTheta: f32, g: f32) -> f32 {
  let g2 = g * g;
  return (1.0 - g2) / (12.566371 * pow(max(1.0 + g2 - 2.0 * g * cosTheta, 1e-4), 1.5));
}

fn groupGain(group: f32) -> f32 {
  return select(select(params.back, params.tube, group < 1.5), params.head, group < 0.5);
}

fn driftDensity(p: vec3f, t: f32) -> f32 {
  let q = p * 0.35 + vec3f(t * 0.05, 0.0, t * 0.03);
  let n = sin(q.x * 1.3 + sin(q.z * 0.9)) * sin(q.z * 1.1 + sin(q.y * 1.7 + q.x * 0.4)) * 0.5 + 0.5;
  return 1.0 + (n - 0.5) * 2.0 * params.drift;
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let lit = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let v = makeView();
  let ray = rayAt(v, uv);
  let z = viewDepth(uv);
  let distance = select(params.reach, z / max(dot(ray, v.forward), 1e-4), z > 0.0);
  let jitter = ignHash(uv * frameU.resolution + vec2f(frameU.absFrame * 5.3, 0.0));
  let dt = distance / f32(STEPS);
  var scatter = vec3f(0.0);
  var optical = 0.0;
  for (var i = 0u; i < STEPS; i = i + 1u) {
    let travel = (f32(i) + jitter) * dt;
    let p = params.eye + ray * travel;
    let sigma = params.density * driftDensity(p, frameU.absTime);
    var inscatter = params.ambient;
    for (var k = 0u; k < LIGHTS; k = k + 1u) {
      let toP = p - L_POS[k];
      let d2 = dot(toP, toP);
      let l = toP * inverseSqrt(max(d2, 1e-6));
      let shape = L_SHAPE[k];
      let cone = select(smoothstep(shape.x, shape.y, dot(l, L_DIR[k])), 1.0, shape.x < -1.5);
      if (cone <= 0.0) { continue; }
      inscatter = inscatter + L_COLOR[k] * groupGain(shape.z) * cone * hg(dot(l, -ray), params.anisotropy) / (d2 + params.core * params.core);
    }
    scatter = scatter + inscatter * sigma * exp(-optical) * dt;
    optical = optical + sigma * dt;
  }
  return vec4f(lit.rgb * exp(-optical) + scatter, lit.a);
}

struct Params {
  threshold: f32, // @default 1.2  Linear radiance where bloom starts.
