// T1400b — the figure's skin (generated by src/projects/on-nothing/skin-kernel.ts from the GLB's bones).
struct Params {
  place: vec3f, // @default 0  Where the figure stands (world metres).
  yaw: f32, // @default 0  Which way it faces: radians about +Y (0 faces +Z).
  pelvis: vec3f, // @default 0  pelvis: rotation about its head, radians (x, y, z about the rest axes).
  spine: vec3f, // @default 0  spine: rotation about its head, radians (x, y, z about the rest axes).
  chest: vec3f, // @default 0  chest: rotation about its head, radians (x, y, z about the rest axes).
