  shinL: vec3f, // @default 0  shin.L: rotation about its head, radians (x, y, z about the rest axes).
  footL: vec3f, // @default 0  foot.L: rotation about its head, radians (x, y, z about the rest axes).
  thighR: vec3f, // @default 0  thigh.R: rotation about its head, radians (x, y, z about the rest axes).
  shinR: vec3f, // @default 0  shin.R: rotation about its head, radians (x, y, z about the rest axes).
  footR: vec3f, // @default 0  foot.R: rotation about its head, radians (x, y, z about the rest axes).
