fn boneAngles(i: u32, ctx: PointCtx) -> vec3f {
  switch i {
    case 0u: { return ctx.params.pelvis; }
    case 1u: { return ctx.params.spine; }
    case 2u: { return ctx.params.chest; }
    case 3u: { return ctx.params.neck; }
    case 4u: { return ctx.params.head; }
    case 5u: { return ctx.params.shoulderL; }
    case 6u: { return ctx.params.upperarmL; }
    case 7u: { return ctx.params.forearmL; }
    case 8u: { return ctx.params.handL; }
    case 9u: { return ctx.params.shoulderR; }
    case 10u: { return ctx.params.upperarmR; }
    case 11u: { return ctx.params.forearmR; }
    case 12u: { return ctx.params.handR; }
    case 13u: { return ctx.params.thighL; }
    case 14u: { return ctx.params.shinL; }
    case 15u: { return ctx.params.footL; }
    case 16u: { return ctx.params.thighR; }
    case 17u: { return ctx.params.shinR; }
    case 18u: { return ctx.params.footR; }
